# make_checked1.py -- builds Final_terms_explicit_1_checked.tex = the author's file Final_terms_explicit_1_author.tex
# unchanged, plus red NOTE boxes at the problems, a red summary at the top and a red-titled UV section (table from
# s10_uv_sec6.json).  Run: python3 -I make_checked1.py
import os, json, re
HERE = os.path.dirname(os.path.abspath(__file__)); TOP = os.path.dirname(HERE)
src = open(os.path.join(TOP, 'Final_terms_explicit_1_author.tex')).read()
s = src
def ins_after(anchor, text, nth=1):
    global s
    i = -1
    for _ in range(nth):
        i = s.index(anchor, i + 1)
    j = i + len(anchor); s = s[:j] + text + s[j:]
def ins_before(anchor, text):
    global s
    i = s.index(anchor); s = s[:i] + text + s[i:]
BOX = r'''
\newcommand{\notebox}[1]{\par\smallskip\noindent\fcolorbox{red}{white}{\parbox{\dimexpr\linewidth-2\fboxsep-2\fboxrule\relax}{\color{red}\small\textbf{NOTE (check of 2026-11-22).} #1}}\par\smallskip}
'''
ins_before(r'\begin{document}', BOX)
DN = open(os.path.join(HERE, 'verified_DeltaN.tex')).read()
DN = DN.replace(r"\ph{(w-w')}", "(w-w')").replace(r'\begin{align}', r'\begin{align}\color{red}').replace(r'\label{eq:B-DN}', r'\label{eq:chk-DN}')
DN = re.sub(r'\\label\{[^}]*\}', '', DN).replace(r'\begin{align}\color{red}', r'\begin{align}\color{red}', 1)
DN = DN.replace(r'\notag', r'\notag').replace('\\end{align}', '\\label{eq:chk-DN}\n\\end{align}')
